  element.style.boxShadow = '0 2px 8px rgba(54, 17, 112, 0.15)';
  element.style.display = 'block';

  var section = element.querySelector('section');
  if (section) {
    section.style.padding = '0';
    section.style.margin = '0';
  }
})();

